inline void enc_request(std::string& out, const Request& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "op");
    out += ": ";
    esc(out, v.op);
    if (!v.name.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "name");
        out += ": ";
        esc(out, v.name);
    }
    if (!v.rights.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "rights");
        out += ": ";
        strs(out, v.rights, depth + 1);
    }
    if (!v.secret.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "secret");
        out += ": ";
        esc(out, v.secret);
    }
    if (!v.token.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "token");
        out += ": ";
        esc(out, v.token);
    }
    if (!v.right.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "right");
        out += ": ";
        esc(out, v.right);
    }
    if (!v.why.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "why");
        out += ": ";
        esc(out, v.why);
    }
    if (!v.app.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "app");
        out += ": ";
        esc(out, v.app);
    }
    if (!v.admin.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "admin");
        out += ": ";
        esc(out, v.admin);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

